  function select(id,{locate=false}={}){fitActive=false;const n=model.byId.get(id);if(!n)return;if(!view.focused)view.overall={...view,expanded:new Set(view.expanded),overall:null};view.focused=true;view.overview=false;if(n.archived)view.archived=true;view.selected=id;draw();if(locate){view.zoom=1;view.x=(canvas.clientWidth-layout.width)/2;view.y=0;transform();}nodes.querySelector(`[data-graph-node="${CSS.escape(id)}"]`)?.focus({preventScroll:true});}
